INSERT INTO achievement_award_log(id,"userId","achievementId","ruleVersion",action,actor,reason,evidence,"idempotencyKey","createdAt") SELECT gen_random_uuid()::text,"userId","achievementId","ruleVersion",'legacy','migration','Existing unlocked award preserved without inferring historical activity','{"basis":"legacy"}'::jsonb,'legacy:'||id,coalesce("unlockedAt","createdAt") FROM public.user_achievements WHERE unlocked ON CONFLICT("idempotencyKey") DO NOTHING;
